function Set-AtaraxiaWpfLocalizedPresentation([System.Collections.IDictionary]$Controls,[object]$Presentation,[string]$ThemePreference) {
    if($null -eq $Controls -or $null -eq $Presentation){throw 'Localized WPF presentation requires controls and presentation data.'}
    $propertyBindings=[ordered]@{
        settings_general_title=@('Text','labels.settings_general');config_label=@('Text','labels.runtime_config');theme_label=@('Text','labels.theme');settings_model_title=@('Text','labels.settings_model');project_prompt_button=@('ToolTip','tooltips.project_prompt');session_prompt_button=@('ToolTip','tooltips.session_prompt');project_group_title=@('Text','labels.project_group');recent_sessions_title=@('Text','labels.recent_sessions');new_project=@('ToolTip','tooltips.new_project');task_name_label=@('Text','labels.task_name');workspace_label=@('Text','labels.working_directory');browse_config=@('ToolTip','tooltips.browse_config');new_session=@('ToolTip','tooltips.new_session');other_session=@('ToolTip','tooltips.session_more');browse_task=@('ToolTip','tooltips.open_task');browse_workspace=@('ToolTip','tooltips.browse_folder');kobold_restart=@('ToolTip','tooltips.kobold_restart');model_file_label=@('Text','labels.model_file');refresh_models=@('ToolTip','tooltips.refresh_models');conversation_label=@('Text','labels.conversation');scroll_latest=@('ToolTip','tooltips.scroll_to_latest');create_task=@('ToolTip','tooltips.new_task');edit_last=@('ToolTip','tooltips.edit_last');run_task=@('ToolTip','tooltips.send_run');save_parameter_preset=@('ToolTip','labels.parameter_preset_save');save_as_parameter_preset=@('ToolTip','labels.parameter_preset_save_as');rename_parameter_preset=@('ToolTip','labels.parameter_preset_rename');delete_parameter_preset=@('ToolTip','labels.parameter_preset_delete')
    }
    foreach($target in $propertyBindings.Keys){if(-not $Controls.Contains($target) -or $null -eq $Controls[$target]){throw "Localized WPF control is not mapped: $target"};$binding=$propertyBindings[$target];$control=$Controls[$target];$property=[string]$binding[0];$localizedValue=$Presentation;$path=[string]$binding[1];foreach($segment in $path.Split('.')){$localizedValue=$localizedValue.$segment};if($null -eq $control.PSObject.Properties[$property]){throw "Localized WPF control does not expose ${property}: $target"};$control.$property=$localizedValue}
    if(-not $Controls.Contains('window') -or -not $Controls.Contains('theme_selector')){throw 'Localized WPF window and theme selector must be mapped.'}
    $window=$Controls.window;$themeSelector=$Controls.theme_selector;if($null -eq $window.Resources['ThemeOptionTemplate']){throw 'WPF theme option template is missing.'};$window.Title=[string]$Presentation.window_title;$window.Tag=[string]$Presentation.window_tag;$themeSelector.ItemsSource=@($Presentation.theme_options);$themeSelector.ItemTemplate=$window.Resources['ThemeOptionTemplate'];$themeSelector.SelectedValuePath='key';$themeSelector.SelectedValue=$ThemePreference
}

function New-AtaraxiaWpfGuiViewPort([System.Collections.IDictionary]$Controls,[System.Collections.IDictionary]$ValueProperties=@{},[scriptblock]$ClipboardTextAdapter,[scriptblock]$InputHeightCalculator) {
