    $controlMap=@{};foreach($key in $Controls.Keys){if([string]::IsNullOrWhiteSpace([string]$key) -or $null -eq $Controls[$key]){throw 'WPF GUI control map contains an invalid entry.'};$controlMap[[string]$key]=$Controls[$key]}
    $propertyMap=@{};foreach($key in $ValueProperties.Keys){$property=[string]$ValueProperties[$key];if($property -notin @('Text','Content','ToolTip','SelectedValue','IsEnabled','Visibility')){throw "WPF GUI value property is not supported: $property"};if(-not $controlMap.ContainsKey([string]$key)){throw "WPF GUI value target is not mapped: $key"};$propertyMap[[string]$key]=$property}
    $setItems={param([string]$Target,[object[]]$Items)if(-not $controlMap.ContainsKey($Target)){throw "WPF GUI item target is not mapped: $Target"};$control=$controlMap[$Target];$property=$control.PSObject.Properties['ItemsSource'];if($null -eq $property){throw "WPF GUI item target does not support ItemsSource: $Target"};$control.ItemsSource=@($Items)}.GetNewClosure()
    $setValue={param([string]$Target,[object]$Value)if(-not $propertyMap.ContainsKey($Target)){throw "WPF GUI value target is not mapped: $Target"};$control=$controlMap[$Target];$property=[string]$propertyMap[$Target];if($null -eq $control.PSObject.Properties[$property]){throw "WPF GUI value target does not expose ${property}: $Target"};if($property -eq 'Visibility'){if($Value -isnot [bool]){throw "WPF GUI visibility values must be boolean: $Target"};$Value=if($Value){'Visible'}else{'Collapsed'}};$control.$property=$Value}.GetNewClosure()
    $registerTarget={param([string]$Target,[object]$Handle)if([string]::IsNullOrWhiteSpace($Target) -or $null -eq $Handle){throw 'WPF GUI target registration requires a key and control.'};$controlMap[$Target]=$Handle}.GetNewClosure()
    $bindAction={param([string]$Target,[string]$Action,[scriptblock]$Handler)if(-not $controlMap.ContainsKey($Target)){throw "WPF GUI action target is not mapped: $Target"};$control=$controlMap[$Target];switch($Action){'activate'{$control.Add_Click($Handler)}'selection_change'{$control.Add_SelectionChanged($Handler)}'text_change'{$control.Add_TextChanged($Handler)}'size_change'{$control.Add_SizeChanged($Handler)}'value_change'{$control.Add_ValueChanged($Handler)}'lost_focus'{$control.Add_LostFocus($Handler)}'expanded_change'{$expandedHandler={param($sender,$eventArgs)& $Handler ([bool]$sender.IsExpanded)}.GetNewClosure();$control.Add_Expanded($expandedHandler);$control.Add_Collapsed($expandedHandler)}'scroll'{$control.Add_ScrollChanged($Handler)}'close'{$control.Add_Closing($Handler)}'content_ready'{$control.Add_ContentRendered($Handler)}'submit'{$control.Add_PreviewKeyDown({param($sender,$eventArgs)if($eventArgs.Key -eq [Windows.Input.Key]::Enter){if([Windows.Input.Keyboard]::Modifiers -band [Windows.Input.ModifierKeys]::Shift){return};$eventArgs.Handled=$true;& $Handler}}.GetNewClosure())}default{throw "WPF GUI action is not supported: $Action"}}}.GetNewClosure()
    $dispatcher=$controlMap['dispatcher']
    $scheduleCallback={param([string]$Priority,[scriptblock]$Callback)switch($Priority){'normal'{$null=$dispatcher.BeginInvoke([Action]$Callback)}'layout_idle'{$null=$dispatcher.BeginInvoke([Windows.Threading.DispatcherPriority]::ContextIdle,[Action]$Callback)}default{throw "WPF GUI scheduling priority is not supported: $Priority"}}}.GetNewClosure()
    $startTimer={param([int]$IntervalMilliseconds,[scriptblock]$Callback)if($IntervalMilliseconds -lt 1){throw 'WPF GUI timer interval must be positive.'};$timer=[Windows.Threading.DispatcherTimer]::new();$timer.Interval=[TimeSpan]::FromMilliseconds($IntervalMilliseconds);$timer.Add_Tick($Callback);$timer.Start();return $timer}.GetNewClosure()
    $stopTimer={param([object]$Handle)if($null -ne $Handle){$Handle.Stop()}}.GetNewClosure()
    $waitDelay={param([int]$Milliseconds)if($Milliseconds -le 0){return};$frame=[Windows.Threading.DispatcherFrame]::new();$timer=[Windows.Threading.DispatcherTimer]::new();$timer.Interval=[TimeSpan]::FromMilliseconds($Milliseconds);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false}.GetNewClosure());$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}.GetNewClosure()
    if($null -eq $ClipboardTextAdapter){$ClipboardTextAdapter={param([string]$Text)[Windows.Clipboard]::SetText($Text)}}
    if($ClipboardTextAdapter -isnot [scriptblock]){throw 'WPF clipboard adapter must be a script block.'}
    if($InputHeightCalculator -isnot [scriptblock]){throw 'WPF input height calculator must be provided.'}
    $invokeViewOperation={param([string]$Operation,[string]$Target,[object]$Value)if(-not $controlMap.ContainsKey($Target)){throw "WPF GUI operation target is not mapped: $Target"};$control=$controlMap[$Target];switch($Operation){'activate_window' {if($control -isnot [Windows.Window]){throw "WPF GUI target is not a window: $Target"};if($control.WindowState -eq [Windows.WindowState]::Minimized){$control.WindowState=[Windows.WindowState]::Normal};if(-not $control.IsVisible){$control.Show()};$null=$control.Activate();$null=$control.Focus()}'focus' {if($null -eq $control.PSObject.Methods['Focus']){throw "WPF GUI target does not support focus: $Target"};$null=$control.Focus()}'scroll_to_end' {if($null -eq $control.PSObject.Methods['ScrollToEnd']){throw "WPF GUI target does not support end scrolling: $Target"};$control.ScrollToEnd()}'scroll_to_top' {if($null -eq $control.PSObject.Methods['ScrollToTop']){throw "WPF GUI target does not support top scrolling: $Target"};$control.ScrollToTop()}'set_text_focus_end' {if($null -eq $control.PSObject.Properties['Text'] -or $null -eq $control.PSObject.Properties['CaretIndex'] -or $null -eq $control.PSObject.Methods['Focus']){throw "WPF GUI target is not an editable text control: $Target"};$control.Text=[string]$Value;$null=$control.Focus();$control.CaretIndex=$control.Text.Length}'toggle_expanded' {if($null -eq $control.PSObject.Properties['IsExpanded']){throw "WPF GUI target does not support expansion: $Target"};$control.IsExpanded=-not [bool]$control.IsExpanded}'open_context_menu' {$menu=$control.ContextMenu;if($null -eq $menu){throw "WPF GUI target has no context menu: $Target"};$menu.PlacementTarget=$control;$menu.IsOpen=$true}'sync_scroll_to_latest_visibility' {if(-not $controlMap.ContainsKey([string]$Value)){throw "WPF scroll target is not mapped: $Value"};$scroll=$controlMap[[string]$Value];if($null -eq $control.PSObject.Properties['Visibility'] -or $null -eq $scroll.PSObject.Properties['ScrollableHeight'] -or $null -eq $scroll.PSObject.Properties['VerticalOffset']){throw 'WPF scroll affordance controls do not expose required visibility and offset values.'};$show=([double]$scroll.ScrollableHeight -gt 8 -and [double]$scroll.VerticalOffset -lt ([double]$scroll.ScrollableHeight-8));$control.Visibility=if($show){'Visible'}else{'Collapsed'}}'update_multiline_input_height' {foreach($property in @('LineCount','FontSize','Padding','MinHeight','MaxHeight','Height')){if($null -eq $control.PSObject.Properties[$property]){throw "WPF GUI input target does not expose ${property}: $Target"}};$verticalPadding=[double]$control.Padding.Top+[double]$control.Padding.Bottom;$control.Height=& $InputHeightCalculator ([int]$control.LineCount) ([double]$control.FontSize) $verticalPadding ([double]$control.MinHeight) ([double]$control.MaxHeight)}default{throw "WPF GUI operation is not supported: $Operation"}}}.GetNewClosure()
    return New-AtaraxiaGuiViewPort $setItems $setValue $bindAction $scheduleCallback $startTimer $stopTimer $waitDelay $registerTarget $ClipboardTextAdapter $invokeViewOperation
